import type { Metadata } from 'next'
import { redirect } from 'next/navigation'
import { getAuthenticatedUser, createClient } from '@/lib/supabase/server'
import { KioskDisplay } from '@/components/consent/kiosk/KioskDisplay'
import type { KioskTemplateOption } from '@/components/consent/kiosk/KioskDisplay'

export const metadata: Metadata = {
  title: 'Kiosk mode — Forms — InkOS',
  // Kiosk display is permanently facing the front desk — don't let it pick up
  // stale caches from the AppHeader flow.
  robots: 'noindex,nofollow',
}

export default async function FormsKioskPage() {
  const auth = await getAuthenticatedUser()
  if (!auth) redirect('/login')

  // Owner + admin + receptionist only. Artists have no legitimate reason to
  // launch kiosk mode, and guests definitely don't.
  if (
    auth.role !== 'owner' &&
    auth.role !== 'admin' &&
    auth.role !== 'receptionist'
  ) {
    redirect('/forms')
  }

  const supabase = await createClient()

  // Fetch picker options + any current session in one trip.
  const [templatesResult, sessionResult] = await Promise.all([
    supabase
      .from('consent_form_templates')
      .select('id, name, kind, is_default')
      .eq('studio_id', auth.studioId)
      .eq('is_active', true)
      .order('is_default', { ascending: false })
      .order('name'),
    supabase
      .from('consent_kiosk_sessions')
      .select('id, kiosk_token, template_id, enabled, last_rotated_at')
      .eq('studio_id', auth.studioId)
      .maybeSingle(),
  ])

  const templates: KioskTemplateOption[] = (templatesResult.data ?? []).map((t) => ({
    id: t.id,
    name: t.name,
    kind: t.kind,
    is_default: t.is_default,
  }))

  const session = sessionResult.data ?? null
  const appUrl = process.env.NEXT_PUBLIC_APP_URL ?? 'http://localhost:3100'

  return (
    <KioskDisplay
      templates={templates}
      initialSession={session}
      appUrl={appUrl}
    />
  )
}

